from collections import Counter, defaultdict, deque

def _components(grid, bg):
    h, w = len(grid), len(grid[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); pts=[]
            while q:
                y,x=q.popleft(); pts.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            out.append((color,pts))
    return out

def _shape(pts):
    return min(tuple(sorted((y-min(a for a,b in pts),x-min(b for a,b in pts)) for y,x in pts)) for _ in [0])

def _norm_shape(pts):
    forms=[]
    for flip in (1,-1):
        for turns in range(4):
            q=[]
            for y,x in pts:
                a,b=y*flip,x
                for _ in range(turns): a,b=b,-a
                q.append((a,b))
            y0=min(y for y,x in q); x0=min(x for y,x in q)
            forms.append(tuple(sorted((y-y0,x-x0) for y,x in q)))
    return min(forms)

def _corner_l(pts):
    if len(pts)!=3: return False
    ys=[y for y,x in pts]; xs=[x for y,x in pts]
    if max(ys)-min(ys)!=1 or max(xs)-min(xs)!=1: return False
    return True

def _large_l(pts):
    ys=[y for y,x in pts]; xs=[x for y,x in pts]
    y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
    hh,ww=y1-y0+1,x1-x0+1
    if hh<3 or ww<3 or len(pts)!=hh+ww-1: return False
    s=set(pts)
    return any(all((yy,x) in s for x in range(x0,x1+1)) and all((y,xx) in s for y in range(y0,y1+1)) for yy in (y0,y1) for xx in (x0,x1))

def _center(pts): return (sum(y for y,x in pts)/len(pts),sum(x for y,x in pts)/len(pts))

